package dev.codex.bedrockpocket;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;

final class AddonManager {
    private static final long MAX_EXPANDED_BYTES=512L*1024L*1024L;
    private static final int MAX_ARCHIVE_ENTRIES=20000;
    private static final class UnpackBudget { long bytes; int entries; }
    static final class Pack { final File directory; final String name,type,version; Pack(File d,String n,String t,String v){directory=d;name=n;type=t;version=v;} }
    static List<Pack> list(File server) {
        ArrayList<Pack> out=new ArrayList<>();
        for(String type:new String[]{"behavior_packs","resource_packs"}) { File root=new File(server,type); File[] dirs=root.listFiles(); if(dirs==null)continue;
            if(java.nio.file.Files.isSymbolicLink(root.toPath()))continue;
            for(File dir:dirs)if(dir.isDirectory()&&!java.nio.file.Files.isSymbolicLink(dir.toPath()))
            try { if(!new File(dir,".bedrockpocket-managed").isFile())continue;JSONObject m=new JSONObject(readUtf8(new File(dir,"manifest.json"))); JSONObject h=m.optJSONObject("header"); JSONArray v=h==null?null:h.optJSONArray("version"); out.add(new Pack(dir,h==null?dir.getName():limit(h.optString("name",dir.getName()),120),type.equals("behavior_packs")?"Behavior Pack":"Resource Pack",v==null?"":limit(v.join("."),64))); } catch(Exception ignored) { }
        }
        out.sort(Comparator.comparing(p->p.name.toLowerCase(Locale.ROOT))); return out;
    }
    static List<Pack> install(File archive,File server)throws Exception {
        File staging=Files.createTempDirectory("bp-addon-").toFile(); ArrayList<Pack> installed=new ArrayList<>();
        try { unpackAny(archive,staging,0,new UnpackBudget()); ArrayList<File> manifests=new ArrayList<>();findManifests(staging,manifests);
            for(File manifest:manifests) { JSONObject json=new JSONObject(readUtf8(manifest));JSONArray modules=json.optJSONArray("modules");String folder=null;
                if(modules!=null)for(int i=0;i<modules.length();i++){JSONObject mod=modules.optJSONObject(i);String t=mod==null?"":mod.optString("type","");if("data".equalsIgnoreCase(t))folder="behavior_packs";if("resources".equalsIgnoreCase(t))folder="resource_packs";}
                if(folder==null)continue;JSONObject h=json.optJSONObject("header");String name=limit(h==null?"Minecraft Add-on":h.optString("name","Minecraft Add-on"),120);String safe=safeComponent(name,80,"pack");JSONArray va=h==null?null:h.optJSONArray("version");String version=safeComponent(va==null?"1":va.join("_"),64,"1");
                File root=new File(server,folder);if(java.nio.file.Files.isSymbolicLink(root.toPath()))throw new IOException("โฟลเดอร์แพ็กเป็น symlink ที่ไม่ปลอดภัย");if(!root.isDirectory()&&!root.mkdirs())throw new IOException("สร้างโฟลเดอร์แพ็กไม่ได้");String serverPath=server.getCanonicalPath()+File.separator;String rootCanonical=root.getCanonicalPath();if(!rootCanonical.startsWith(serverPath))throw new IOException("โฟลเดอร์แพ็กอยู่นอกพื้นที่เซิร์ฟเวอร์");String directoryName=safe+"_"+version;File dest=new File(root,directoryName);int suffix=2;while(dest.exists())dest=new File(root,directoryName+"_"+(suffix++));String rootPath=rootCanonical+File.separator;if(!dest.getCanonicalPath().startsWith(rootPath))throw new IOException("ชื่อแพ็กพยายามออกนอกโฟลเดอร์แพ็ก");copyTree(manifest.getParentFile(),dest);if(!new File(dest,".bedrockpocket-managed").createNewFile())throw new IOException("ทำเครื่องหมายแพ็กที่ติดตั้งไม่สำเร็จ");installed.add(new Pack(dest,name,folder.equals("behavior_packs")?"Behavior Pack":"Resource Pack",version));
            }
            if(installed.isEmpty())throw new IOException("ไม่พบ manifest ของ Behavior Pack หรือ Resource Pack ในไฟล์นี้");activateInstalled(server);return installed;
        } finally {deleteTree(staging);}
    }
    private static void unpackAny(File input,File destination,int depth,UnpackBudget budget)throws Exception {
        if(depth>4)throw new IOException("ไฟล์ add-on ซ้อนกันลึกเกินไป");File out=new File(destination,"content_"+depth);if(!out.mkdirs())throw new IOException("สร้างพื้นที่ชั่วคราวไม่ได้");boolean archive=false;
        try(ZipInputStream zin=new ZipInputStream(new BufferedInputStream(new FileInputStream(input)))){ZipEntry e;byte[] b=new byte[32768];while((e=zin.getNextEntry())!=null){if(++budget.entries>MAX_ARCHIVE_ENTRIES)throw new IOException("ไฟล์ add-on มีรายการมากเกินกำหนด (20,000 รายการ)");String entryName=e.getName();validateArchivePath(entryName);File target=new File(out,entryName);String root=out.getCanonicalPath()+File.separator;if(!target.getCanonicalPath().startsWith(root))throw new IOException("พบพาธไม่ปลอดภัยในไฟล์ add-on");if(e.isDirectory()){if(!target.mkdirs()&&!target.isDirectory())throw new IOException("สร้างโฟลเดอร์ชั่วคราวไม่ได้");continue;}File parent=target.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("สร้างโฟลเดอร์ชั่วคราวไม่ได้");if(target.exists())throw new IOException("ไฟล์ add-on มีรายการซ้ำ");try(FileOutputStream os=new FileOutputStream(target)){int n;while((n=zin.read(b))>0){budget.bytes+=n;if(budget.bytes>MAX_EXPANDED_BYTES)throw new IOException("ไฟล์ add-on แตกออกมาใหญ่เกิน 512 MB");os.write(b,0,n);}}archive=true;}}
        catch(ZipException e){deleteTree(out);return;}if(!archive)return;ArrayList<File> nested=new ArrayList<>();collectArchives(out,nested);for(File f:nested)unpackAny(f,out,depth+1,budget);
    }
    private static void collectArchives(File f,List<File> out){File[] a=f.listFiles();if(a==null)return;for(File x:a)if(x.isDirectory()&&!java.nio.file.Files.isSymbolicLink(x.toPath()))collectArchives(x,out);else if(x.isFile()&&!java.nio.file.Files.isSymbolicLink(x.toPath())&&(x.getName().toLowerCase(Locale.ROOT).endsWith(".mcpack")||x.getName().toLowerCase(Locale.ROOT).endsWith(".mcaddon")))out.add(x);}
    private static void findManifests(File f,List<File> out){File[] a=f.listFiles();if(a==null)return;for(File x:a)if(x.isDirectory()&&!java.nio.file.Files.isSymbolicLink(x.toPath()))findManifests(x,out);else if(x.isFile()&&!java.nio.file.Files.isSymbolicLink(x.toPath())&&x.getName().equalsIgnoreCase("manifest.json"))out.add(x);}
    static void activateInstalled(File server)throws IOException {
        String level="Bedrock level";File properties=new File(server,"server.properties");if(java.nio.file.Files.isSymbolicLink(properties.toPath()))throw new IOException("server.properties เป็น symlink ที่ไม่ปลอดภัย");if(properties.isFile())try{for(String line:Files.readAllLines(properties.toPath()))if(line.startsWith("level-name=")){level=line.substring("level-name=".length()).trim();break;}}catch(Exception e){throw new IOException("อ่าน server.properties ไม่ได้",e);}if(level.isEmpty()||level.equals(".")||level.equals("..")||level.contains("/")||level.contains("\\"))throw new IOException("level-name ไม่ใช่ชื่อโฟลเดอร์โลกที่ปลอดภัย");
        File worlds=new File(server,"worlds");if(java.nio.file.Files.isSymbolicLink(worlds.toPath()))throw new IOException("โฟลเดอร์ worlds เป็น symlink ที่ไม่ปลอดภัย");if(!worlds.isDirectory()&&!worlds.mkdirs())throw new IOException("สร้างโฟลเดอร์ worlds ไม่ได้");File world=new File(worlds,level);if(java.nio.file.Files.isSymbolicLink(world.toPath()))throw new IOException("โฟลเดอร์โลกเป็น symlink ที่ไม่ปลอดภัย");if(!world.isDirectory()&&!world.mkdirs())throw new IOException("สร้างโฟลเดอร์โลกสำหรับเปิดใช้แอดออนไม่ได้");if(!world.getCanonicalPath().startsWith(worlds.getCanonicalPath()+File.separator))throw new IOException("โฟลเดอร์โลกอยู่นอก worlds");
        for(String type:new String[]{"behavior_packs","resource_packs"}){File root=new File(server,type);if(java.nio.file.Files.isSymbolicLink(root.toPath()))throw new IOException("โฟลเดอร์แพ็กเป็น symlink ที่ไม่ปลอดภัย");File[] packs=root.listFiles();if(packs==null)continue;File packList=new File(world,type.equals("behavior_packs")?"world_behavior_packs.json":"world_resource_packs.json");if(java.nio.file.Files.isSymbolicLink(packList.toPath()))throw new IOException("รายการแพ็กโลกเป็น symlink ที่ไม่ปลอดภัย");JSONArray entries=readArray(packList);boolean changed=false;
            for(File pack:packs)try{if(!pack.isDirectory()||java.nio.file.Files.isSymbolicLink(pack.toPath())||!new File(pack,".bedrockpocket-managed").isFile())continue;JSONObject manifest=new JSONObject(readUtf8(new File(pack,"manifest.json")));JSONObject header=manifest.optJSONObject("header");if(header==null)continue;String uuid=header.optString("uuid","");JSONArray version=header.optJSONArray("version");if(uuid.isEmpty()||version==null)continue;boolean found=false;for(int i=0;i<entries.length();i++)if(uuid.equalsIgnoreCase(entries.optJSONObject(i)==null?"":entries.optJSONObject(i).optString("pack_id",""))){found=true;break;}if(!found){JSONObject entry=new JSONObject();entry.put("pack_id",uuid);entry.put("version",version);entries.put(entry);changed=true;}}
            catch(Exception e){throw new IOException("อ่าน manifest ไม่สำเร็จ: "+pack.getName(),e);}if(changed)writeArray(new File(world,type.equals("behavior_packs")?"world_behavior_packs.json":"world_resource_packs.json"),entries);
        }
    }
    private static JSONArray readArray(File f)throws IOException{if(java.nio.file.Files.isSymbolicLink(f.toPath()))throw new IOException("รายการแพ็กเป็น symlink ที่ไม่ปลอดภัย");if(!f.isFile())return new JSONArray();try{return new JSONArray(readUtf8(f));}catch(Exception e){throw new IOException("รายการแพ็กของโลกอ่านไม่ได้: "+f.getName(),e);}}
    private static String readUtf8(File f)throws IOException{if(!f.isFile()||f.length()>1024*1024)throw new IOException("manifest.json ใหญ่เกินขนาด 1 MB หรืออ่านไม่ได้");return new String(Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8);}
    private static void writeArray(File f,JSONArray values)throws IOException{File temp=new File(f.getParentFile(),f.getName()+".tmp");Files.write(temp.toPath(),values.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));try{Files.move(temp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){temp.delete();throw new IOException("บันทึกรายการแพ็กไม่สำเร็จ: "+f.getName(),e);}}
    static void copyTree(File src,File dst)throws IOException{if(java.nio.file.Files.isSymbolicLink(src.toPath()))throw new IOException("พบ symlink ในแพ็ก add-on");if(!dst.mkdirs()&&!dst.isDirectory())throw new IOException("สร้างโฟลเดอร์แพ็กไม่สำเร็จ");File[] a=src.listFiles();if(a==null)throw new IOException("อ่านไฟล์แพ็กไม่ได้");for(File x:a){if(java.nio.file.Files.isSymbolicLink(x.toPath()))throw new IOException("พบ symlink ในแพ็ก add-on");File y=new File(dst,x.getName());if(x.isDirectory())copyTree(x,y);else Files.copy(x.toPath(),y.toPath());}}
    static void deleteTree(File f)throws IOException{if(java.nio.file.Files.isSymbolicLink(f.toPath())){Files.delete(f.toPath());return;}if(!f.exists())return;File[] a=f.listFiles();if(a!=null)for(File x:a)deleteTree(x);if(!f.delete())throw new IOException("ลบไม่ได้: "+f.getName());}
    private static String limit(String value,int max){if(value==null)return "";return value.length()<=max?value:value.substring(0,max);}
    private static String safeComponent(String value,int max,String fallback){String safe=limit(value==null?"":value,max).replaceAll("[^A-Za-z0-9._-]","_");return safe.isEmpty()||safe.equals(".")||safe.equals("..")?fallback:safe;}
    private static void validateArchivePath(String name)throws IOException{if(name==null||name.isEmpty()||name.length()>4096||name.startsWith("/")||name.startsWith("\\")||name.contains("\\")||name.indexOf('\0')>=0||name.indexOf(':')>=0)throw new IOException("พบพาธไม่ปลอดภัยในไฟล์ add-on");String[] parts=name.split("/",-1);if(parts.length>64)throw new IOException("พาธในไฟล์ add-on ซ้อนลึกเกินไป");for(int i=0;i<parts.length;i++)if(parts[i].equals(".")||parts[i].equals("..")||(parts[i].isEmpty()&&i!=parts.length-1))throw new IOException("พบพาธไม่ปลอดภัยในไฟล์ add-on");}
}
